                              '      setWindow128k();\n'
                              '      const generateText = mockSummarySideQuery();\n'
                              '\n'
                              '      const result = await service.compress(mockChat, '
                              '{\n'
                              '        promptId: mockPromptId,\n'
                              '        force: false,\n'
                              '        config: mockConfig,\n'
                              '        consecutiveFailures: 0,\n'
                              '        originalTokenCount: 50_000,\n'
                              '      });\n'
                              '\n'
                              '      '
                              'expect(result.info.compressionStatus).toBe(CompressionStatus.COMPRESSED);\n'
                              '      expect(generateText).toHaveBeenCalled();\n'
