                              '\n'
                              "describe('computeThresholds', () => {\n"
                              "  it('32K window — degenerate ceiling, proportional "
                              "floor governs auto', () => {\n"
                              '    // effectiveWindow 12K, ceiling = 12K - 13K = -1K '
                              '(≤ 0) → auto falls back to\n'
                              '    // the proportional floor (0.85 * 32K).\n'
                              '    const t = computeThresholds(32_000);\n'
                              '    expect(t.warn).toBe(7_200); // auto - WARN_BUFFER = '
                              '27.2K - 20K\n'
                              '    expect(t.auto).toBe(27_200); // proportional floor: '
                              '0.85 * 32K\n'
                              '    expect(t.hard).toBe(30_200); // auto + HARD_BUFFER '
                              '= 27.2K + 3K\n'
                              '    expect(t.effectiveWindow).toBe(12_000);\n'
                              '  });\n'
                              '\n'
                              "  it('60K window — ceiling governs auto; hard stays "
                              "above auto (issue #4945)', () => {\n"
                              '    // ceiling = ew(40K) - 13K = 27K < '
                              'proportional(51K) → auto = ceiling.\n'
                              '    const t = computeThresholds(60_000);\n'
                              '    expect(t.warn).toBe(7_000); // auto - WARN_BUFFER = '
                              '27K - 20K\n'
                              '    expect(t.auto).toBe(27_000); // min(0.85*60K=51K, '
                              'ew-13K=27K)\n'
                              '    expect(t.hard).toBe(37_000); // ew - HARD_BUFFER = '
                              '40K - 3K\n'
                              '    expect(t.hard).toBeGreaterThan(t.auto);\n'
                              '    expect(t.effectiveWindow).toBe(40_000);\n'
                              '  });\n'
                              '\n'
                              "  it('128K window — ceiling governs auto (leaves room "
                              "to compress)', () => {\n"
                              '    // ceiling = ew(108K) - 13K = 95K < '
                              'proportional(108.8K) → auto = ceiling.\n'
                              '    // auto + SUMMARY_RESERVE = 95K + 20K = 115K ≤ '
                              '128K, so the summary fits.\n'
                              '    const t = computeThresholds(128_000);\n'
                              '    expect(t.warn).toBe(75_000); // auto - WARN_BUFFER '
                              '= 95K - 20K\n'
                              '    expect(t.auto).toBe(95_000); // '
                              'min(0.85*128K=108.8K, ew-13K=95K)\n'
                              '    expect(t.hard).toBe(105_000); // ew - HARD_BUFFER = '
                              '108K - 3K\n'
                              '    expect(t.effectiveWindow).toBe(108_000);\n'
                              '  });\n'
                              '\n'
                              "  it('200K window — ceiling governs auto (167K), just "
                              "below proportional', () => {\n"
                              '    // ceiling = ew(180K) - 13K = 167K < '
                              'proportional(170K) → auto = 167K.\n'
                              '    const t = computeThresholds(200_000);\n'
                              '    expect(t.warn).toBe(147_000); // auto - WARN_BUFFER '
                              '= 167K - 20K\n'
                              '    expect(t.auto).toBe(167_000); // '
                              'min(0.85*200K=170K, ew-13K=167K)\n'
                              '    expect(t.hard).toBe(177_000); // ew - HARD_BUFFER = '
                              '180K - 3K\n'
                              '  });\n'
                              '\n'
                              "  it('1M window — proportional governs auto (85%), "
                              "never crowds the ceiling', () => {\n"
                              '    // proportional(850K) < ceiling(967K) → auto = '
                              '850K, not ~97% of the window.\n'
                              '    const t = computeThresholds(1_000_000);\n'
                              '    expect(t.warn).toBe(830_000); // auto - WARN_BUFFER '
                              '= 850K - 20K\n'
                              '    expect(t.auto).toBe(850_000); // min(0.85*1M=850K, '
                              'ew-13K=967K)\n'
                              '    expect(t.hard).toBe(977_000); // ew - HARD_BUFFER = '
                              '980K - 3K\n'
                              '  });\n'
                              '\n'
                              "  it('extreme small window (10K) does not crash; "
                              "returns sane values', () => {\n"
                              '    const t = computeThresholds(10_000);\n'
                              '    expect(t.auto).toBeGreaterThan(0);\n'
                              '    expect(t.warn).toBeGreaterThanOrEqual(0);\n'
                              '    expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                              '    expect(t.auto).toBeLessThanOrEqual(t.hard);\n'
                              '    // window < SUMMARY_RESERVE: effectiveWindow clamps '
                              'to 0 and the ceiling is\n'
                              '    // negative, so auto falls back to the proportional '
                              'floor (0.85 * 10K = 8.5K);\n'
                              '    // warn = max(0, 8.5K - 20K) = 0.\n'
                              '    expect(t.auto).toBe(8_500);\n'
                              '    expect(t.warn).toBe(0);\n'
                              '    expect(t.effectiveWindow).toBe(0);\n'
                              '  });\n'
                              '\n'
                              "  it('zero window returns effectiveWindow=0 and "
                              "non-negative tiers', () => {\n"
                              '    const t = computeThresholds(0);\n'
                              '    expect(t.effectiveWindow).toBe(0);\n'
                              '    expect(t.warn).toBe(0);\n'
                              '    expect(t.auto).toBe(0);\n'
                              '    expect(t.hard).toBe(0);\n'
                              '  });\n'
                              '\n'
                              "  it('thresholds always satisfy warn <= auto < hard for "
                              "non-zero windows', () => {\n"
                              '    for (const w of [\n'
                              '      10_000, 32_000, 60_000, 64_000, 128_000, 200_000, '
                              '256_000, 1_000_000,\n'
                              '    ]) {\n'
                              '      const t = computeThresholds(w);\n'
                              '      expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                              '      expect(t.auto).toBeLessThan(t.hard);\n'
                              '    }\n'
                              '  });\n'
                              '\n'
                              "  describe('custom pct parameter', () => {\n"
                              "    it('uses DEFAULT_PCT when pct is not provided', () "
                              '=> {\n'
                              '      const defaultResult = computeThresholds(32_000);\n'
                              '      const explicitDefault = computeThresholds(32_000, '
                              '0.85);\n'
                              '      expect(explicitDefault).toEqual(defaultResult);\n'
                              '    });\n'
                              '\n'
                              "    it('custom pct=0.5 lowers the proportional floor on "
                              "a degenerate window', () => {\n"
                              '      // 32K: ceiling ≤ 0 → auto = proportional floor = '
                              '0.5 * 32K.\n'
                              '      const t = computeThresholds(32_000, 0.5);\n'
                              '      expect(t.auto).toBe(16_000); // 0.5 * 32K\n'
                              '      expect(t.warn).toBe(0); // max(0, 16K - 20K)\n'
                              '    });\n'
                              '\n'
                              "    it('custom pct=0.9 raises the proportional floor on "
                              "a degenerate window', () => {\n"
                              '      const t = computeThresholds(32_000, 0.9);\n'
                              '      expect(t.auto).toBe(28_800); // 0.9 * 32K\n'
                              '      expect(t.warn).toBe(8_800); // 28.8K - 20K\n'
                              '    });\n'
                              '\n'
                              "    it('custom pct DOES pull auto earlier on large "
                              "windows (ceiling semantics)', () => {\n"
                              '      // Under min-semantics the proportional term '
                              'governs large windows, so a\n'
                              '      // lower pct compacts earlier — matching '
                              "claude-code's Math.min override.\n"
                              '      const defaultResult = '
                              'computeThresholds(1_000_000);\n'
                              '      const customPct = computeThresholds(1_000_000, '
                              '0.5);\n'
                              '      expect(defaultResult.auto).toBe(850_000); // 0.85 '
                              '* 1M\n'
                              '      expect(customPct.auto).toBe(500_000); // 0.5 * 1M '
                              '< ceiling(967K)\n'
                              '      '
                              'expect(customPct.auto).toBeLessThan(defaultResult.auto);\n'
                              '    });\n'
                              '\n'
                              "    it('custom pct preserves warn <= auto < hard "
                              "invariant', () => {\n"
                              '      for (const pct of [0.3, 0.5, 0.6, 0.8, 0.9]) {\n'
                              '        for (const w of [10_000, 32_000, 128_000, '
                              '200_000]) {\n'
                              '          const t = computeThresholds(w, pct);\n'
                              '          expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                              '          expect(t.auto).toBeLessThan(t.hard);\n'
                              '        }\n'
                              '      }\n'
                              '    });\n'
                              '\n'
                              "    it('pct=0 produces auto=0 for small windows "
                              "(proportional floor is 0)', () => {\n"
                              '      const t = computeThresholds(32_000, 0);\n'
                              '      // 0 * 32000 = 0; ceiling is negative → auto = '
                              'proportional floor = 0.\n'
                              '      expect(t.auto).toBe(0);\n'
                              '      // warn = max(0, 0 - WARN_BUFFER) = 0\n'
                              '      expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                              '      // hard is clamped to max(rawHard, auto + '
                              'HARD_BUFFER)\n'
                              '      expect(t.hard).toBeGreaterThan(t.auto);\n'
                              '    });\n'
                              '\n'
                              "    it('pct=1 sets proportional auto to full window; "
                              "hard may equal auto for small windows', () => {\n"
                              '      const t = computeThresholds(32_000, 1);\n'
                              '      expect(t.auto).toBe(32_000);\n'
                              '      expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                              '      // For 32K window: hard = min(32000, '
                              'max(effectiveWindow - HARD_BUFFER, 32000 + '
                              'HARD_BUFFER)) = 32000\n'
