                             '\n'
                             'import type { Content, GenerateContentConfig } from '
                             "'@google/genai';\n"
                             'import { beforeEach, describe, expect, it, vi } from '
                             "'vitest';\n"
                             "import type { Config } from '../config/config.js';\n"
                             "import { ApprovalMode } from '../config/config.js';\n"
                             'import type {\n'
                             '  GenerateTextOptions,\n'
                             '  GenerateTextResult,\n'
                             "} from '../core/baseLlmClient.js';\n"
                             "import { AuthType } from '../core/contentGenerator.js';\n"
                             'import {\n'
                             '  FinishReason,\n'
                             '  FunctionCallingConfigMode,\n'
                             "} from '../core/genai-compat.js';\n"
                             'import type { GeminiChat } from '
                             "'../core/geminiChat.js';\n"
                             "import { CompressionStatus } from '../core/turn.js';\n"
                             'import { ORPHAN_TOOL_USE_REPAIR_REASON } from '
                             "'../core/toolOutcome.js';\n"
                             'import * as attachments from '
                             "'./postCompactAttachments.js';\n"
                             'import {\n'
                             '  AUTOCOMPACT_BUFFER,\n'
                             '  COMPACT_FINAL_RESPONSE_TOKEN_BUDGET,\n'
                             '  COMPACT_MAX_OUTPUT_TOKENS,\n'
                             '  COMPACT_THINKING_TOKEN_BUDGET,\n'
                             '  ChatCompressionService,\n'
                             '  DEFAULT_PCT,\n'
                             '  HARD_BUFFER,\n'
                             '  MAX_CONSECUTIVE_FAILURES,\n'
                             '  SUMMARY_RESERVE,\n'
                             '  WARN_BUFFER,\n'
                             '  computeThresholds,\n'
                             "} from './chatCompressionService.js';\n"
                             '\n'
                             "const MODEL = 'Qwen3.8-27B-NVFP4';\n"
                             'const WINDOW = 262_144;\n'
                             '\n'
                             "function snapshot(body = 'complete state'): string {\n"
                             '  return '
                             '`<state_snapshot><current_work>${body}</current_work></state_snapshot>`;\n'
                             '}\n'
                             '\n'
                             'function summaryResult(\n'
                             '  overrides: Partial<GenerateTextResult> = {},\n'
                             '): GenerateTextResult {\n'
                             '  return {\n'
                             '    text: snapshot(),\n'
                             '    finishReason: FinishReason.STOP,\n'
                             '    hadToolCall: false,\n'
                             '    usage: {\n'
                             '      promptTokenCount: 220_000,\n'
                             '      candidatesTokenCount: 2_000,\n'
                             '      totalTokenCount: 222_000,\n'
                             '    },\n'
                             '    ...overrides,\n'
                             '  };\n'
                             '}\n'
                             '\n'
                             'function baseHistory(): Content[] {\n'
                             '  return [\n'
                             "    { role: 'user', parts: [{ text: 'Investigate the "
                             "repository.' }] },\n"
                             "    { role: 'model', parts: [{ text: 'I inspected the "
                             "source.' }] },\n"
                             '  ];\n'
                             '}\n'
                             '\n'
                             'interface Harness {\n'
                             '  config: Config;\n'
                             '  chat: GeminiChat;\n'
                             '  history: Content[];\n'
                             '  countSideQuery: ReturnType<typeof vi.fn>;\n'
                             '  generateText: ReturnType<typeof vi.fn>;\n'
                             '  countCandidate: ReturnType<typeof vi.fn>;\n'
                             '  firePreCompactEvent: ReturnType<typeof vi.fn>;\n'
                             '  firePostCompactEvent: ReturnType<typeof vi.fn>;\n'
                             '  debug: ReturnType<typeof vi.fn>;\n'
                             '  warn: ReturnType<typeof vi.fn>;\n'
                             '  generationConfig: GenerateContentConfig;\n'
                             '  contentGeneratorConfig: {\n'
                             '    model: string;\n'
                             '    authType: AuthType;\n'
                             "    exactTokenCounting?: 'vllm';\n"
                             '    contextWindowSize: number;\n'
                             '    enableCacheControl?: boolean;\n'
                             '  };\n'
                             '  setCompactionModel(model: string | undefined): void;\n'
                             '  setHistory(history: Content[]): void;\n'
                             '  setAutoThreshold(value: number): void;\n'
                             '  setHookSystem(enabled: boolean): void;\n'
                             '}\n'
                             '\n'
                             'function makeHarness(): Harness {\n'
                             '  let history = baseHistory();\n'
                             '  let compactionModel: string | undefined = MODEL;\n'
                             '  let autoThreshold = 1;\n'
                             '  let hooksEnabled = false;\n'
                             '  const generationConfig: GenerateContentConfig = {\n'
                             "    systemInstruction: 'main agent system prompt',\n"
                             "    tools: [{ functionDeclarations: [{ name: 'read_file' "
                             '}] }],\n'
                             '  };\n'
                             '  const contentGeneratorConfig = {\n'
                             '    model: MODEL,\n'
                             '    authType: AuthType.USE_GEMINI,\n'
                             "    exactTokenCounting: 'vllm' as const,\n"
                             '    contextWindowSize: WINDOW,\n'
                             '  };\n'
                             '  const countSideQuery = vi.fn().mockResolvedValue({\n'
                             '    totalTokens: 225_000,\n'
                             '    maxModelLen: WINDOW,\n'
                             '  });\n'
                             '  const generateText = '
                             'vi.fn().mockResolvedValue(summaryResult());\n'
                             '  const countCandidate = vi\n'
                             '    .fn()\n'
                             '    .mockResolvedValueOnce({ totalTokens: 230_000, '
                             'maxModelLen: WINDOW })\n'
                             '    .mockResolvedValueOnce({ totalTokens: 12_000, '
                             'maxModelLen: WINDOW });\n'
                             '  const firePreCompactEvent = '
                             'vi.fn().mockResolvedValue(undefined);\n'
                             '  const firePostCompactEvent = '
                             'vi.fn().mockResolvedValue(undefined);\n'
                             '  const debug = vi.fn();\n'
                             '  const warn = vi.fn();\n'
                             '  const hookSystem = {\n'
                             '    firePreCompactEvent,\n'
                             '    firePostCompactEvent,\n'
                             '  };\n'
                             '  const baseLlmClient = { countRequestTokens: '
                             'countSideQuery, generateText };\n'
                             '  const config = {\n'
                             '    getChatCompression: () => ({\n'
                             '      maxRecentFiles: 0,\n'
                             '      maxRecentImages: 0,\n'
                             '      enableScreenshotTrigger: false,\n'
                             '    }),\n'
                             '    getContentGeneratorConfig: () => '
                             'contentGeneratorConfig,\n'
                             '    getAutoCompactThreshold: () => autoThreshold,\n'
                             '    getHookSystem: () => (hooksEnabled ? hookSystem : '
                             'undefined),\n'
                             '    getCompactionModel: () => compactionModel,\n'
                             '    getModel: () => MODEL,\n'
                             '    getBaseLlmClient: () => baseLlmClient,\n'
                             '    getDebugLogger: () => ({ debug, warn }),\n'
                             "    getTargetDir: () => '/workspace',\n"
                             '    getApprovalMode: () => ApprovalMode.DEFAULT,\n'
                             '    getBackgroundTaskRegistry: () => undefined,\n'
                             '    getUsageStatisticsEnabled: () => false,\n'
                             "    getSessionId: () => 'compaction-test-session',\n"
                             '  } as unknown as Config;\n'
                             '  const chat = {\n'
                             '    getHistoryShallow: () => history.map((entry) => ({ '
                             '...entry })),\n'
                             '    getGenerationConfig: () => ({ ...generationConfig '
                             '}),\n'
                             '    countRequestTokensForCandidateHistory: '
                             'countCandidate,\n'
                             '  } as unknown as GeminiChat;\n'
                             '\n'
                             '  return {\n'
                             '    config,\n'
                             '    chat,\n'
                             '    get history() {\n'
                             '      return history;\n'
                             '    },\n'
                             '    countSideQuery,\n'
                             '    generateText,\n'
                             '    countCandidate,\n'
                             '    firePreCompactEvent,\n'
                             '    firePostCompactEvent,\n'
                             '    debug,\n'
                             '    warn,\n'
                             '    generationConfig,\n'
                             '    contentGeneratorConfig,\n'
                             '    setCompactionModel(model) {\n'
                             '      compactionModel = model;\n'
                             '    },\n'
                             '    setHistory(next) {\n'
                             '      history = next;\n'
                             '    },\n'
                             '    setAutoThreshold(value) {\n'
                             '      autoThreshold = value;\n'
                             '    },\n'
                             '    setHookSystem(enabled) {\n'
                             '      hooksEnabled = enabled;\n'
                             '    },\n'
                             '  };\n'
                             '}\n'
                             '\n'
                             'async function compress(\n'
                             '  harness: Harness,\n'
                             '  overrides: {\n'
                             '    force?: boolean;\n'
                             "    trigger?: 'manual' | 'auto';\n"
                             '    originalTokenCount?: number;\n'
                             '    consecutiveFailures?: number;\n'
                             '    pendingUserMessage?: Content;\n'
                             '    precomputedEffectiveTokens?: number;\n'
                             '    requestGenerationConfig?: GenerateContentConfig;\n'
                             '    customInstructions?: string;\n'
                             '    signal?: AbortSignal;\n'
                             '  } = {},\n'
                             ') {\n'
                             '  return new '
                             'ChatCompressionService().compress(harness.chat, {\n'
                             "    promptId: 'compaction-contract',\n"
                             '    force: overrides.force ?? true,\n'
                             '    trigger: overrides.trigger,\n'
                             '    config: harness.config,\n'
                             '    consecutiveFailures: overrides.consecutiveFailures '
                             '?? 0,\n'
                             '    originalTokenCount: overrides.originalTokenCount ?? '
                             '230_000,\n'
                             '    pendingUserMessage: overrides.pendingUserMessage,\n'
                             '    precomputedEffectiveTokens: '
                             'overrides.precomputedEffectiveTokens,\n'
                             '    requestGenerationConfig: '
                             'overrides.requestGenerationConfig,\n'
                             '    customInstructions: overrides.customInstructions,\n'
                             '    signal: overrides.signal,\n'
                             '  });\n'
                             '}\n'
                             '\n'
                             "describe('computeThresholds', () => {\n"
                             "  it('uses the exact native-window ladder selected by "
                             "the deployment', () => {\n"
                             '    expect(computeThresholds(WINDOW, 1)).toEqual({\n'
                             '      effectiveWindow: WINDOW - SUMMARY_RESERVE,\n'
                             '      warn: WINDOW - SUMMARY_RESERVE - '
                             'AUTOCOMPACT_BUFFER - WARN_BUFFER,\n'
                             '      auto: WINDOW - SUMMARY_RESERVE - '
                             'AUTOCOMPACT_BUFFER,\n'
                             '      hard: WINDOW - SUMMARY_RESERVE - HARD_BUFFER,\n'
                             '    });\n'
                             '  });\n'
                             '\n'
                             '  it.each([32_000, 60_000, 128_000, 200_000, '
                             '1_000_000])(\n'
                             "    'keeps ordered non-negative thresholds for "
                             "window=%i',\n"
                             '    (window) => {\n'
                             '      const thresholds = computeThresholds(window);\n'
                             '      '
                             'expect(thresholds.warn).toBeGreaterThanOrEqual(0);\n'
                             '      '
                             'expect(thresholds.warn).toBeLessThanOrEqual(thresholds.auto);\n'
                             '      '
                             'expect(thresholds.auto).toBeLessThanOrEqual(thresholds.hard);\n'
                             '      '
                             'expect(thresholds.hard).toBeLessThanOrEqual(window);\n'
                             '    },\n'
                             '  );\n'
                             '\n'
                             "  it('uses DEFAULT_PCT for non-finite input and clamps "
                             "percentages', () => {\n"
                             '    expect(computeThresholds(1_000_000, '
                             'Number.NaN).auto).toBe(\n'
                             '      DEFAULT_PCT * 1_000_000,\n'
                             '    );\n'
                             '    expect(computeThresholds(10_000, -1).auto).toBe(0);\n'
                             '    expect(computeThresholds(10_000, '
                             '2).auto).toBe(10_000);\n'
                             '  });\n'
                             '});\n'
                             '\n'
                             "describe('ChatCompressionService single exact mode', () "
                             '=> {\n'
                             '  beforeEach(() => {\n'
                             '    vi.restoreAllMocks();\n'
                             '    vi.spyOn(attachments, '
                             "'composePostCompactHistory').mockResolvedValue([\n"
                             "      { role: 'user', parts: [{ text: "
                             "snapshot('replacement') }] },\n"
                             "      { role: 'model', parts: [{ text: 'ack' }] },\n"
                             '    ]);\n'
                             '  });\n'
                             '\n'
                             "  it('NOOPs before side effects when history or "
                             "threshold state cannot compact', async () => {\n"
                             '    const empty = makeHarness();\n'
                             '    empty.setHistory([]);\n'
                             '    expect((await '
                             'compress(empty)).info.compressionStatus).toBe(\n'
                             '      CompressionStatus.NOOP,\n'
                             '    );\n'
                             '    expect(empty.generateText).not.toHaveBeenCalled();\n'
                             '\n'
                             '    const oneTurn = makeHarness();\n'
                             "    oneTurn.setHistory([{ role: 'user', parts: [{ text: "
                             "'only one' }] }]);\n"
                             '    expect((await '
                             'compress(oneTurn)).info.compressionStatus).toBe(\n'
                             '      CompressionStatus.NOOP,\n'
                             '    );\n'
                             '\n'
                             '    const below = makeHarness();\n'
