                      "  await walk(root, '');\n"
                      '  if (failures.length > 0) {\n'
                      "    const preview = failures.slice(0, 20).join('; ');\n"
                      '    throw new Qwen38EffectJournalError(\n'
                      '      `${label} effect snapshot is incomplete '
                      '(${failures.length} failures): ${preview}`,\n'
                      '    );\n'
