                      'Array<\n'
                      '    [keyof Qwen38EffectPaths, string[]]\n'
                      '  >) {\n'
                      '    lines.push(`${label}.${kind}.count=${paths.length}`);\n'
                      '    for (const item of paths) {\n'
                      '      if (remaining.value === 0) continue;\n'
                      '      '
                      'lines.push(`${label}.${kind}.path=${JSON.stringify(item)}`);\n'
                      '      remaining.value -= 1;\n'
                      '    }\n'
                      '  }\n'
