                             '\n'
                             'async function hashRegularFile(filePath: string): '
                             'Promise<ManifestEntry> {\n'
                             '  const handle = await fs.open(\n'
                             '    filePath,\n'
                             '    constants.O_RDONLY | constants.O_NOFOLLOW,\n'
                             '  );\n'
                             '  try {\n'
