                             '      fd: handle.fd,\n'
                             '      autoClose: false,\n'
                             '    });\n'
                             '    for await (const chunk of stream) hash.update(chunk '
                             'as Buffer);\n'
                             '    const after = await handle.stat();\n'
                             '    if (\n'
                             '      before.dev !== after.dev ||\n'
                             '      before.ino !== after.ino ||\n'
                             '      before.size !== after.size ||\n'
