                             '  const rootStat = await fs.lstat(root);\n'
                             '  if (!rootStat.isDirectory() || '
                             'rootStat.isSymbolicLink()) {\n'
                             '    throw new Qwen38EffectJournalError(\n'
                             '      `${label} root is not a real directory: ${root}`,\n'
                             '    );\n'
                             '  }\n'
